import{_ as i,o as a,c as r,ae as t}from"./chunks/framework.CK6jtcgr.js";const p=JSON.parse('{"title":"Threat Model","description":"","frontmatter":{},"headers":[],"relativePath":"threat-model.md","filePath":"threat-model.md"}'),l={name:"threat-model.md"};function s(o,e,n,u,c,d){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="threat-model" tabindex="-1">Threat Model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat Model&quot;">​</a></h1><p>This document captures baseline risks, trust boundaries, and security invariants for SocioProphet.</p><hr><h2 id="trust-boundaries" tabindex="-1">Trust boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to &quot;Trust boundaries&quot;">​</a></h2><ul><li>The browser is untrusted.</li><li>Firestore rules are the authoritative access control boundary for client-originated reads/writes.</li><li>CI is the merge gate that prevents policy regression.</li><li>Production deploy is assumed hostile-by-default until proven otherwise.</li></ul><hr><h2 id="primary-risks-and-controls" tabindex="-1">Primary risks and controls <a class="header-anchor" href="#primary-risks-and-controls" aria-label="Permalink to &quot;Primary risks and controls&quot;">​</a></h2><h3 id="_1-secret-leakage" tabindex="-1">1) Secret leakage <a class="header-anchor" href="#_1-secret-leakage" aria-label="Permalink to &quot;1) Secret leakage&quot;">​</a></h3><p>Risk:</p><ul><li>Secrets committed to git.</li><li>Build-time environment variables embedded into client artifacts.</li></ul><p>Controls:</p><ul><li>Secret scanning in CI (gitleaks/other scanners).</li><li>Runtime public config pattern (<code>public/firebase-config.js</code>) instead of env injection.</li><li><code>.gitignore</code> rules that keep local config untracked.</li></ul><hr><h3 id="_2-over-permissive-firestore-rules" tabindex="-1">2) Over-permissive Firestore rules <a class="header-anchor" href="#_2-over-permissive-firestore-rules" aria-label="Permalink to &quot;2) Over-permissive Firestore rules&quot;">​</a></h3><p>Risk:</p><ul><li>Public read/write exposure.</li><li>Rule drift over time.</li><li>“Temporary allow-all” becoming permanent.</li></ul><p>Controls:</p><ul><li>Deny-by-default as the baseline.</li><li>Explicit allow rules only when backed by tests.</li><li>Emulator-backed rules tests running locally and in CI.</li><li>Small, reviewable changes to rules.</li></ul><hr><h3 id="_3-ci-bypass-unsafe-merges" tabindex="-1">3) CI bypass / unsafe merges <a class="header-anchor" href="#_3-ci-bypass-unsafe-merges" aria-label="Permalink to &quot;3) CI bypass / unsafe merges&quot;">​</a></h3><p>Risk:</p><ul><li>Direct pushes to protected branch.</li><li>Merging without security checks.</li></ul><p>Controls:</p><ul><li>Branch protection with required status checks.</li><li>CI workflows for secret scanning and rules tests.</li><li>Minimal, auditable workflows stored in-repo.</li></ul><hr><h3 id="_4-privilege-escalation-via-mutable-fields" tabindex="-1">4) Privilege escalation via mutable fields <a class="header-anchor" href="#_4-privilege-escalation-via-mutable-fields" aria-label="Permalink to &quot;4) Privilege escalation via mutable fields&quot;">​</a></h3><p>Risk:</p><ul><li>Changing ownership fields to hijack records.</li><li>Mutating fields that must be immutable.</li></ul><p>Controls:</p><ul><li>Immutable-field constraints in Firestore rules when collections are introduced.</li><li>Owner-based checks (<code>request.auth.uid</code>) where applicable.</li><li>Tests that prove the invariants.</li></ul><hr><h2 id="security-invariants" tabindex="-1">Security invariants <a class="header-anchor" href="#security-invariants" aria-label="Permalink to &quot;Security invariants&quot;">​</a></h2><ol><li>Default deny everywhere unless explicitly opened.</li><li>No secrets in git history or build artifacts.</li><li>All datastore expansions must be test-backed.</li><li>Public config is intentionally public and loaded at runtime.</li></ol>',33)])])}const m=i(l,[["render",s]]);export{p as __pageData,m as default};
